<section class="panel"><h1>پیگیری سفارش</h1><p>کد محرمانه پیگیری را که پس از ثبت سفارش دریافت کردید وارد کنید. این کد را در اختیار دیگران قرار ندهید.</p>
<?php if($error): ?><p class="flash flash-error"><?= CHtml::encode($error) ?></p><?php endif; ?>
<?= CHtml::beginForm('','post') ?><label for="token">کد محرمانه پیگیری</label><?= CHtml::textField('token','',array('maxlength'=>64,'required'=>true,'dir'=>'ltr','autocomplete'=>'off')) ?><?= CHtml::submitButton('پیگیری',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?>
<?php if($order): ?><h2><?= CHtml::encode($order->order_number) ?></h2><?= OrderPresentation::badge($order->status) ?><p>ثبت: <?= JalaliDate::format($order->created_at) ?></p><p>مبلغ: <?= Money::format($order->total) ?></p><p>کد مرسوله: <?= CHtml::encode($order->tracking_code?:'هنوز ثبت نشده') ?></p><?php foreach($order->items as $item): ?><p><?= CHtml::encode($item->product_title) ?> × <?= (int)$item->quantity ?></p><?php endforeach; ?><?php if(Zarinpal::enabled()&&in_array($order->status,array('pending','confirmed'),true)): ?><?= CHtml::beginForm(array('payment/start','number'=>$order->order_number),'post') ?><?= CHtml::hiddenField('token',$token) ?><?= CHtml::submitButton('پرداخت با زرین‌پال',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?><?php endif; ?><?php endif; ?></section>
